    ArrayList a2 = new ArrayList();
    a2.add(a1);
    // a2 content: [[8, "a1String"]] - basically [a1]
    // a2 has one item - a1
    ArrayList a3 = new ArrayList();
    a3.addAll(a1);
    // a3 content: [8, "a1String"] - same content as a1
    // a3 has all the items from a1

