    private void merge(List> same) {
    if (!same.isEmpty()) {
    // Now find min max
    Date min = null;
    Date max = null;
    for (HashMap i : same) {
    Date from = (Date) i.get("fromDate");
    Date to = (Date) i.get("toDate");
    if (min == null) {
    min = from;
    }
    else if (from.before(min)) {
    min = from;
    }
    if (max == null) {
    max = to;
    }
    else if (to.after(max)) {
    max = to;
    }
    }
    for (HashMap i : same) {
    i.put("fromDate", min);
    i.put("toDate", max);
    }
    }
    }
