How to get sub-Collections form collection Java (Collections, Arrays, List) and keep track of last one returned 


    public Collection getCommentCollection() {
    commentCollection = movie.getCommentCollection(); 
    return split((List) commentCollection, 4);
    }
    public Collection split(List list, int size){
    int numBatches = (list.size() / size) + 1;
    Collection[] batches = new Collection[numBatches];
    Collection set = commentCollection;
    for(int index = 0; index < numBatches; index++) {
    int count = index + 1;
    int fromIndex = Math.max(((count - 1) * size), 0);
    int toIndex = Math.min((count * size), list.size());
    batches[index] = list.subList(fromIndex, toIndex);
    set = batches[index];
    }
    return set;
    }


