    for (int i = 0; i < 900000; i++) {
    hashSet.add(String.valueOf(i));
    }
    System.out.println("Insert HashSet Time: " + (System.currentTimeMillis() - start));
    ArrayList arrayList = new ArrayList();
    start = System.currentTimeMillis();
