    Test test = new Test();
    for (int i=0;i<1000000000;i++) {
    test.doStuff();//or dostuff2
    }
    long t2 = System.nanoTime();
    System.err.println((t2-t1)/1000000);
    System.err.println(counter); // to check it wasnt optimised away
    }
