    private Empleado empleado;
    @OneToMany(cascade = CascadeType.ALL)
    private List productos = new ArrayList();
    private Date fechaDeIngreso;
    public Venta() {
    }
    public Venta(Integer numero_factura, Empleado empleado, List productos, Date fechaDeIngreso) {
    super();
    this.numero_factura = numero_factura;
    this.empleado = empleado;
    this.productos = productos;
    this.fechaDeIngreso = fechaDeIngreso;
    }
    @Override
    public boolean equals(Object objeto) {
    if (objeto == null) {
    return false;
    }
    if (this == objeto) {
    return true;
    }
    if (objeto instanceof Venta) {
    Venta otraVenta = (Venta) objeto;
    if (otraVenta.getNumero_factura() == this.numero_factura) {
    return true;
    }
    }
    return false;
    }
    public Integer getNumero_factura() {
    return numero_factura;
    }
    public void setNumero_factura(Integer numero_factura) {
    this.numero_factura = numero_factura;
    }
    public Empleado getEmpleado() {
    return empleado;
    }
    public void setEmpleado(Empleado empleado) {
    this.empleado = empleado;
    }
    public List getProductos() {
    return productos;
    }
    public void setProductos(List productos) {
    this.productos = productos;
    }
    public Date getFechaDeIngreso() {
    return fechaDeIngreso;
    }
    public void setFechaDeIngreso(Date fechaDeIngreso) {
    this.fechaDeIngreso = fechaDeIngreso;
    }
    }


