    lst = new ArrayList();
    // initialise UNSORTED array
    fruits[0] = "Melon"; fruits[1] = "apricot"; fruits[2] = "peach";
    fruits[3] = "mango"; fruits[4] = "Apple"; fruits[5] = "pineapple";
    fruits[6] = "banana";
    }
    public static void main(String[] args) {
    Sorter srt = new Sorter();
    srt.anyOldUnstaticMethod();
    }
