    public static List flatten(Object object) {
    return (List) recursiveFlatten(object, true);
    }
    public static Set uniqFlatten(Object object) {
    return (Set) recursiveFlatten(object, false);
    }
    private static Collection recursiveFlatten(Object object, Boolean allowDuplicates) {
    Collection setOrList;
    if (allowDuplicates) {
    setOrList = new ArrayList();
    } else {
    setOrList = new LinkedHashSet();
    }
    if (object.getClass().isArray()) {
    for (int i = 0; i < Array.getLength(object); i++) {
    setOrList.addAll(recursiveFlatten(Array.get(object, i), allowDuplicates));
    }
    } else if (object instanceof Map) {
    for (Object element : ((Map) object).values()) {
    setOrList.addAll(recursiveFlatten(element, allowDuplicates));
    }
    } else if (object instanceof Iterable) {
    for (Object element : (Iterable) object) {
    setOrList.addAll(recursiveFlatten(element, allowDuplicates));
    }
    } else {
    setOrList.add(object);
    }
    return setOrList;
    }
    }


