    setA = new HashSet();
    setA.add("Testing...");
    setB = new HashSet();
    setB.add("Testing...");
    }
    @Test
    public void testEqualSets() {
    assertEquals( setA, setB );
    }
    }


This test will pass if the two Sets are the same size and contain the same elements.

