    var1.add("Two");
    var1.add("Three");
    System.out.println("var1 : " + var1);
    try{
    if(Collections.addAll(var1,"Four" , "Five" , null , "1")){
    System.out.println("True"); 
    }
    }
    catch(NullPointerException e){
    System.out.println("Caught Null Pointer Exception" + e);
    }
