    long timeAL = timeAddToArrayList();
    long timeLL = timeAddsToLinkedList();
    System.out.printf("Time to add %,d Integer to ArrayList %.3f sec, LinkedList %.3f%n",
    TO_ADD, timeAL / 1e9, timeLL / 1e9);
    }
