    lsFalse.add("goodbye3");
    lsFalse.add("goodbye4");
    lsFalse.add("goodbye5");
    System.out.println("true: " + Arrays.deepToString(lsTrue.toArray()));
    System.out.println("false: " + Arrays.deepToString(lsFalse.toArray()));
    }
    }


