    compact();
    return super.comparator();
    }
    @Override
    public E first() {
    compact();
    return super.first();
    }
    @Override
    public E last() {
    compact();
    return super.last();
    }
    @Override
    public E lower(E e) {
    compact();
    return super.lower(e);
    }
    @Override
    public E floor(E e) {
    compact();
    return super.floor(e);
    }
    @Override
    public E ceiling(E e) {
    compact();
    return super.ceiling(e);
    }
    @Override
    public E higher(E e) {
    compact();
    return super.higher(e);
    }
    @Override
    public E pollFirst() {
    compact();
    return super.pollFirst();
    }
    @Override
    public E pollLast() {
    compact();
    return super.pollLast();
    }
    @Override
    public boolean removeAll(Collection c) {
    compact();
    return super.removeAll(c);
    }
    @Override
    public Object[] toArray() {
    compact();
    return super.toArray();
    }
    @Override
    public  T[] toArray(T[] a) {
    compact();
    return super.toArray(a);
    }
    @Override
