    l1.add(i);
    }
    assert TO_ADD == l1.size();
    return System.nanoTime() - starttime;
    }
    private static long timeAddsToLinkedList() {
    long starttime = System.nanoTime();
    List l2 = new LinkedList();
    for (int i = 1; i <= TO_ADD; i++) {
    l2.add(i);
    }
    assert TO_ADD == l2.size();
    return System.nanoTime() - starttime;
    }
