    public int hashCode() {
    final int prime = 31;
    int result = 1;
    result = prime * result + intB;
    result = prime * result + ((strB == null) ? 0 : strB.hashCode());
    return result;
    }
    private int intB;
    private String strB;
    private boolean boolB;
    // Constructor
    public ClassB(int intB, String strB, boolean boolB) {
